      "id": 1,
      "claim": "Atmospheric pressure decreases as altitude increases.",
      "evidence": "Barometric formula: pressure ≈ 101 kPa at sea level and drops to ~80 kPa at typical high‑mountain elevations (~2–3 km).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "When the bottle was open on the summit, the air inside it was at the same low pressure as the surrounding atmosphere.",
      "evidence": "An open container equilibrates its internal pressure with the external pressure.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "After the water was drunk, the bottle was sealed, trapping that low‑pressure air inside.",
      "evidence": "Closing the cap fixes the amount of gas and its pressure at the moment of sealing.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Descending to the valley raises the external atmospheric pressure to a higher value than at the summit.",
      "evidence": "Pressure increases with decreasing altitude; typical valley pressure ≈ 101 kPa versus ~80 kPa at the summit.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "The higher external pressure relative to the trapped lower internal pressure compresses the thin‑walled plastic bottle, causing it to collapse.",
      "evidence": "A pressure differential across a flexible shell produces a net inward force; the ~20 kPa over‑pressure exceeds the buckling strength of common PET bottles.",
      "weight": 0.30,
      "depends_on": [3, 4]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Temperature differences alone would not create a sufficient pressure imbalance; the observed collapse is explained by the pressure change with altitude."
    },
    {
      "answer": "B",
      "reason_rejected": "Higher temperature in the valley would increase internal pressure, opposing collapse rather than causing it."
    },
    {
      "answer": "C",
      "reason_rejected": "Air pressure is higher, not lower, in the valley; a lower external pressure would make the bottle expand, not collapse."
    }
  ]
}
